import { complete, fragment as f, section as s, walkthrough, type Walkthrough } from './basics-helpers.ts';

export const bronzeWalkthroughs: Record<string, Walkthrough> = {
  'pensar-en-algoritmos': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Cada paquete del taller lleva dos lápices y un cuaderno. Tenemos l lápices y c cuadernos. Queremos preparar tantos paquetes completos como sea posible. Los sobrantes pueden quedar sin usar.\n\nLa entrada contiene l y c, ambos entre 0 y 10⁹. La salida es el máximo número de paquetes. Con once lápices y tres cuadernos podemos hacer tres paquetes.', { example: { input: '11 3\n', output: '3\n' } }),
    s('Primero, armar paquetes a mano', 'Podríamos ir retirando dos lápices y un cuaderno mientras alcance. Con 11 y 3, los recursos quedarían en (9, 2), luego (7, 1) y finalmente (5, 0). Ya no queda un cuaderno para otro paquete.\n\nLa simulación sirve para entender las reglas, pero podría repetir el mismo paso cientos de millones de veces. Podemos contar grupos completos mediante divisiones.'),
    s('Cada recurso impone un límite', 'Con l lápices no puedes hacer más de l / 2 paquetes completos. Con c cuadernos no puedes hacer más de c. Tienes que respetar las dos restricciones, así que debes elegir el menor de esos números.\n\nCon once lápices, la primera cota es cinco. Los tres cuadernos la reducen a tres. Tres sí se alcanza: consume seis lápices y tres cuadernos. No solo encontramos un límite; mostramos una manera de cumplirlo.', { picture: { caption: 'Un recurso puede sobrar aunque el otro se agote.', rows: [{ label: 'Recurso', values: ['Lápices', 'Cuadernos'] }, { label: 'Disponibles', values: ['11', '3'] }, { label: 'Por paquete', values: ['2', '1'] }, { label: 'Paquetes que permiten', values: ['5', '3'] }] } }),
    f('Convertir el razonamiento en instrucciones', 'Primero calculamos el límite de los lápices. Si los cuadernos permiten menos, lo reducimos:', 'long long paquetes = l / 2;\nif (c < paquetes) paquetes = c;\ncout << paquetes << "\\n";', 'paquetes siempre representa una cantidad completa, porque l / 2 es división entera. No necesitamos un ciclo para descontar cada paquete. Una descripción precisa de estos pasos, incluso sin sintaxis C++, es un algoritmo.'),
    complete(lesson, 'El programa hace las dos lecturas, calcula ambos límites y muestra el menor. El número de operaciones no depende de cuántos paquetes produzca.', 'Prueba 0 5, 10 0 y 10 5. Deben salir 0, 0 y 5. Si la receta cambia a tres lápices y dos cuadernos, compara l / 3 con c / 2: los divisores vienen del enunciado.'),
    s('Cómo comprobar otra idea', 'Buscar un caso que contradiga una regla puede evitar programar una solución incorrecta. Por ejemplo, «siempre basta dividir los lápices entre dos» falla con 11 y 3. Un solo caso válido alcanza para descartarla.\n\nPara defender una regla necesitas un argumento general. Aquí demostramos que ninguna respuesta puede superar el menor límite y que esa cantidad siempre se puede construir. La solución usa O(1) tiempo y memoria.'),
  ]),
  complejidad: lesson => walkthrough([
    s('El problema que vamos a resolver', 'Hay n participantes y queremos contar cuántas parejas distintas se pueden formar. Una persona no puede emparejarse consigo misma, y elegir A con B es lo mismo que B con A.\n\nn está entre 1 y 10⁹. Para cuatro participantes A, B, C y D hay seis parejas: AB, AC, AD, BC, BD y CD. Solo debemos imprimir la cantidad, no la lista de parejas.', { example: { input: '4\n', output: '6\n' } }),
    f('Una solución que enumera todas', 'Podemos representar cada persona por un índice y visitar cada pareja i < j:', 'long long parejas = 0;\nfor (long long i = 0; i < n; i++) {\n    for (long long j = i + 1; j < n; j++) {\n        parejas++;\n    }\n}', 'Para n = 4, el ciclo interior hace 3, 2, 1 y 0 vueltas. Para n = 1000 son 499 500 en total. Para n = 10⁹ serían casi 5 × 10¹⁷: la lista de instrucciones es corta, pero su ejecución no.\n\nLa **complejidad** describe cómo crece ese trabajo con el tamaño de entrada. Esta enumeración cuesta O(n²).'),
    s('Contar sin construir cada pareja', 'Cada una de las n personas puede elegir a otras n − 1. Eso da n(n − 1), pero cuenta dos veces cada pareja: A con B y B con A. Dividimos entre dos.\n\nPara cuatro personas: 4 × 3 / 2 = 6. La fórmula obtiene el total sin visitar seis parejas, y tampoco necesita visitarlas cuando n es grande.'),
    f('Una fórmula de costo constante', 'Leemos n como long long para que también la multiplicación use ese tipo:', 'cout << n * (n - 1) / 2 << "\\n";', 'El producto máximo es menor que 10¹⁸ y cabe en long long. Hacemos una resta, una multiplicación y una división: O(1) operaciones con enteros de tamaño fijo. Si el problema pidiera imprimir todas las parejas, esa fórmula no produciría la salida requerida.'),
    complete(lesson, 'El programa completo calcula únicamente la cantidad solicitada. No necesita guardar la identidad de los participantes.', 'Prueba n = 1 y n = 2: deben salir 0 y 1. Estos casos revisan que no contemos parejas de una persona consigo misma.'),
    s('Distinguir otros crecimientos', 'Dos recorridos separados de n datos hacen aproximadamente 2n pasos: O(n). Dos recorridos completos anidados hacen n²: O(n²). Un ciclo que duplica su índice pasa por 1, 2, 4, 8… y necesita O(log n) vueltas.\n\nLa notación no da segundos exactos. Sirve para comparar el crecimiento y descartar cantidades de trabajo absurdas para los límites. La memoria se cuenta aparte: guardar n enteros de 64 bits ocupa unos 8n bytes para los datos; un acumulador fijo usa O(1) espacio adicional.'),
  ]),
  ordenamiento: lesson => walkthrough([
    s('El problema que vamos a resolver', 'Recibimos n tiempos de entrenamiento y una posición k. Queremos el k-ésimo tiempo más pequeño, contando repeticiones. La entrada da n y k, después los n tiempos.\n\nSe cumple 1 ≤ k ≤ n ≤ 100 000. Para [7, 3, 7, 1, 3] y k = 3, la respuesta es 3: ordenados quedan [1, 3, 3, 7, 7].', { example: { input: '5 3\n7 3 7 1 3\n', output: '3\n' } }),
    s('Qué cambia al ordenar', 'Ordenar de menor a mayor cambia las posiciones para que cada elemento sea menor o igual al siguiente. No elimina datos repetidos. Los dos tiempos de 3 siguen ocupando dos lugares.\n\nPodríamos buscar el mínimo repetidamente hasta llegar al tercero, cuidando qué aparición quitamos. Ordenar toda la lista da una forma directa de consultar cualquier posición por tamaño.', { picture: { caption: 'La posición pedida se cuenta desde uno; el vector usa índices desde cero.', rows: [{ label: 'Lugar por tamaño', values: ['1', '2', '3', '4', '5'] }, { label: 'Índice', values: ['0', '1', '2', '3', '4'] }, { label: 'Tiempo ordenado', values: ['1', '3', '3', '7', '7'], highlight: [2] }] } }),
    f('Pedirle a la biblioteca que ordene', 'Incluimos <algorithm> y llamamos a sort sobre el vector completo:', 'sort(a.begin(), a.end());\ncout << a[k - 1] << "\\n";', 'begin señala el inicio y end el lugar inmediatamente posterior al último elemento. sort ordena ese intervalo. El dato que pide k está en índice k − 1.\n\nCon k = n consultamos a[n − 1], no a[n]. Los límites del enunciado garantizan que la posición existe.'),
    complete(lesson, 'El programa guarda los tiempos en el vector a. En su lectura, `for (auto &x : a)` recorre cada casilla; auto deduce su tipo y & permite guardar el número leído dentro de esa casilla. Es otra forma de leer a[i] con un índice.', 'Prueba k = 1, k = n y varios valores iguales. La respuesta cuenta apariciones. Si quisieras el segundo valor distinto, tendrías que plantear otra operación.'),
    s('Conservar el dato que todavía necesitas', 'Después de ordenar, a[0] ya no se refiere necesariamente al primer estudiante de la entrada. Si necesitas identificar a esa persona, guarda una pareja (tiempo, índice original) antes de ordenar.\n\nsort no garantiza conservar el orden original entre elementos equivalentes según su comparador. Si ese orden importa, necesitas un desempate o un ordenamiento estable.'),
    s('Cuándo vale la pena ordenar', 'sort realiza O(n log n) comparaciones. Leer y consultar después no elimina ese costo. El vector ocupa O(n) memoria.\n\nSi solo te piden el mínimo una vez, un recorrido O(n) basta. Para obtener el segundo mayor después de ordenar ascendente, la posición es n − 2; en general, el k-ésimo mayor está en n − k. La convención de índices depende de la pregunta.'),
  ]),
  'busqueda-exhaustiva': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Tienes un presupuesto b y n materiales con precios conocidos. Debes comprar exactamente dos materiales de posiciones distintas. Queremos gastar lo máximo posible sin superar b. Si no existe una pareja válida, imprimimos −1.\n\nHay entre 2 y 200 materiales; los precios no son negativos. Para [2, 6, 5, 9] y presupuesto 10, la mejor compra cuesta 8: los materiales de precios 2 y 6.', { example: { input: '4 10\n2 6 5 9\n', output: '8\n' } }),
    s('Enumerar las opciones sin adivinar', 'Podemos probar todas las parejas. Con cuatro posiciones son (0,1), (0,2), (0,3), (1,2), (1,3) y (2,3). Sus sumas son 8, 7, 11, 11, 15 y 14. Solo 8 y 7 caben.\n\nEsto es **búsqueda exhaustiva**: consideramos todas las opciones permitidas. No basta con probar las que parecen prometedoras si no podemos justificar por qué descartamos las otras.'),
    f('Generar cada pareja una sola vez', 'El segundo índice empieza justo después del primero:', 'for (int i = 0; i < n; ++i) {\n    for (int j = i + 1; j < n; ++j) {\n        long long s = a[i] + a[j];\n        if (s <= b && s > mejor) mejor = s;\n    }\n}', 'i < j evita elegir una misma casilla dos veces y evita contar los dos órdenes de una pareja. Precios iguales en posiciones distintas sí pueden comprarse juntos.\n\nLa condición tiene dos trabajos: `s <= b` comprueba si la compra cabe; `s > mejor` decide si mejora lo encontrado.'),
    f('Recordar si existe una respuesta', 'Antes de los ciclos inicializamos el mejor costo:', 'long long mejor = -1;', 'Cualquier costo válido es al menos cero. Por eso −1 permite reconocer que todavía no encontramos una pareja. Inicializar en cero confundiría «no hay compra» con una compra válida de dos materiales gratuitos.\n\nDespués de revisar cada pareja, mejor conserva el costo más alto entre las válidas ya visitadas. Como todas las parejas aparecen, al terminar también apareció una óptima.'),
    complete(lesson, 'El programa usa long long para presupuestos y sumas. La muestra permite comprobar las seis parejas a mano antes de ejecutar.', 'Prueba dos materiales de precios 8 y 9 con presupuesto 10: debe salir −1. Prueba dos ceros con presupuesto cero: debe salir 0. En ambos casos se exige comprar exactamente dos.'),
    s('El límite permite revisar todo', 'Hay n(n − 1)/2 parejas. Para n = 200 son 19 900: una búsqueda O(n²) es adecuada aquí. Para 200 000 datos serían casi veinte mil millones y necesitaríamos otra idea.\n\nUna solución exhaustiva pequeña también puede servir como referencia al probar una más rápida. Pero si el enunciado cambia a «como máximo dos materiales», habrá que considerar además compras de uno y de cero; estos ciclos solo generan parejas.'),
  ]),
  voraces: lesson => walkthrough([
    s('El problema que vamos a resolver', 'Queremos pagar exactamente m usando monedas de 1, 5 y 10. Hay todas las monedas que necesitemos. La salida es la menor cantidad de monedas posible; m va de 0 a 10⁹.\n\nPara 28 podemos usar dos monedas de diez, una de cinco y tres de uno. Son seis monedas. Vamos a justificar por qué no podemos usar menos.', { example: { input: '28\n', output: '6\n' } }),
    s('Proponer una elección local', 'Una regla posible es tomar tantas monedas de diez como quepan, después monedas de cinco y al final unos. Es una regla **voraz**: decide usando lo que queda y no vuelve a cambiar las elecciones anteriores.\n\nPara 28, tomamos dos dieces y quedan 8; un cinco deja 3; tres unos terminan el pago. Que funcione en esta cuenta todavía no prueba que siempre minimice monedas.'),
    s('Por qué el intercambio mejora cualquier otra forma', 'Si una solución usa cinco unos, podemos cambiarlos por un cinco y reducir la cantidad de monedas. Por tanto, una solución mínima tiene a lo sumo cuatro unos. Si usa dos cincos, podemos cambiarlos por un diez, así que tiene a lo sumo un cinco.\n\nCon esas dos restricciones, las monedas de uno y cinco suman menos de diez. Todo lo demás debe pagarse con dieces. Esa forma es exactamente la que produce nuestra regla. Los intercambios conservan el valor y reducen monedas.'),
    f('Calcular cuántas monedas caben', 'No necesitamos repetir una instrucción por moneda. Las divisiones y residuos hacen la cuenta:', 'long long dieces = m / 10;\nlong long pendiente = m % 10;\nlong long cincos = pendiente / 5;\nlong long unos = pendiente % 5;\ncout << dieces + cincos + unos << "\\n";', 'Para 28 obtenemos dieces = 2, pendiente = 8, cincos = 1 y unos = 3. Como diez es múltiplo de cinco, `(m % 10) % 5` también es igual a `m % 5`; el programa completo usa esa forma compacta.'),
    complete(lesson, 'La respuesta se obtiene con un número fijo de operaciones, O(1) tiempo y memoria. Si m es cero, todas las cantidades también son cero.', 'Prueba 4, 5, 9, 10 y 18. Para 18, cambiar dos cincos por un diez explica por qué tres cincos y tres unos no son la mejor opción.'),
    s('Una regla parecida puede fallar', 'Con monedas de 1, 3 y 4, elegir la mayor primero paga 6 como 4 + 1 + 1: tres monedas. Pero 3 + 3 usa dos. La regla queda refutada para esas denominaciones.\n\nUn algoritmo voraz necesita una razón ligada a las reglas del problema. Antes de aplicarlo a otra tarea, busca tanto un contraejemplo como una forma de transformar una solución óptima sin empeorarla.'),
  ]),
  'usaco-bronze-time-comp': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Para cada entero i entre 1 y n, se visitan sus múltiplos i, 2i, 3i y así hasta n. Queremos contar el total de visitas, incluyendo las repeticiones entre distintos i.\n\nn está entre 1 y 1 000 000. Para n = 5 hay cinco visitas con i = 1, dos con i = 2 y una con cada i de 3 a 5. El total es 10.', { example: { input: '5\n', output: '10\n' } }),
    f('Simular las visitas', 'Esta versión ejecuta literalmente cada visita:', 'long long total = 0;\nfor (int i = 1; i <= n; i++) {\n    for (int j = i; j <= n; j += i) {\n        total++;\n    }\n}', 'El ciclo interior no siempre hace n vueltas. Para i = 2 salta de dos en dos; para i = 5 salta de cinco en cinco. Ver dos ciclos anidados no basta para concluir que hacen n² visitas.'),
    s('Contar una fila sin recorrerla', 'Los múltiplos de i son i, 2i, …, ki, donde k es el mayor entero que cumple ki ≤ n. Por tanto, hay n / i usando división entera. Para n = 10 e i = 3, aparecen 3, 6 y 9: tres visitas.', { picture: { caption: 'Cada columna cuenta la fila de un valor de i.', rows: [{ label: 'i para n = 5', values: ['1', '2', '3', '4', '5'] }, { label: 'Múltiplos', values: ['1,2,3,4,5', '2,4', '3', '4', '5'] }, { label: 'n / i', values: ['5', '2', '1', '1', '1'] }] } }),
    f('Sumar las cantidades', 'Como solo piden el total, reemplazamos el ciclo interior por una división:', 'long long total = 0;\nfor (int i = 1; i <= n; ++i) {\n    total += n / i;\n}', 'Ahora ejecutamos n divisiones: O(n) tiempo y O(1) memoria. Conservamos las repeticiones: una visita al número cuatro con i = 1 y otra con i = 2 cuentan por separado.'),
    complete(lesson, 'El acumulador es long long. Con n = 10, los cocientes son 10, 5, 3, 2, 2, 1, 1, 1, 1 y 1, que suman 27.', 'Prueba n = 1 y n = 5. Distingue el número que imprimimos del trabajo realizado: la respuesta puede ser mayor que n, aunque el programa haga solo n vueltas.'),
    s('El costo de la simulación original', 'La versión anidada hace aproximadamente n/1 + n/2 + … + n/n visitas. Agrupa los i en [1,2), [2,4), [4,8)… Cada bloque tiene a lo sumo 2ᵏ índices y cada uno aporta a lo sumo n/2ᵏ visitas: el bloque aporta a lo sumo n.\n\nHay O(log n) bloques, por lo que esa simulación cuesta O(n log n). O(n²) también sería una cota superior, pero menos precisa. Si necesitáramos imprimir cada visita, no podríamos sustituirlas por una suma de cantidades.'),
  ]),
  'usaco-bronze-intro-ds': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Recibimos n votos numéricos entre 0 y 100. Queremos el valor más frecuente. Si varios empatan, elegimos el menor. n está entre 1 y 100 000.\n\nPara [4, 1, 4, 2, 1, 4], el 4 aparece tres veces, el 1 dos veces y el 2 una. Respondemos 4.', { example: { input: '6\n4 1 4 2 1 4\n', output: '4\n' } }),
    s('Guardar lo que hace falta para responder', 'Podríamos guardar la lista y, para cada valor, volver a contar sus apariciones. Como los valores posibles son pocos, podemos reservar un contador para cada uno.\n\nUna **estructura de datos** es una forma de organizar información para las operaciones que necesitas. Aquí elegimos una tabla de frecuencias: la casilla f[x] guarda cuántas veces apareció x. No guarda el dato que estaba en la posición x de la lista original.'),
    f('Construir los contadores', 'Creamos 101 casillas para incluir los valores del 0 al 100. Todas empiezan en cero:', 'vector<int> f(101, 0);\nfor (int i = 0; i < n; ++i) {\n    int x;\n    cin >> x;\n    ++f[x];\n}', 'Cada lectura cambia solo el contador correspondiente. Con los seis votos de la muestra, f[1] vale 2, f[2] vale 1 y f[4] vale 3. Todos los demás quedan en cero.\n\nEl rango del enunciado hace válido usar x como índice. Si x pudiera ser mil millones, esta tabla ya no sería una elección razonable.'),
    f('Encontrar el ganador y resolver empates', 'mejor guarda el valor candidato, no su frecuencia. Comparamos mediante f:', 'int mejor = 0;\nfor (int x = 1; x <= 100; ++x) {\n    if (f[x] > f[mejor]) mejor = x;\n}', 'Recorremos de menor a mayor y cambiamos solo con frecuencia estrictamente mayor. En un empate se conserva el valor menor que ya habíamos visitado. Usar >= reemplazaría el candidato por el mayor empatado.'),
    complete(lesson, 'La lista original no es necesaria porque solo preguntamos por cantidades de apariciones. La tabla conserva esa información y pierde el orden de llegada.', 'Prueba [2, 1, 2, 1]: debe responder 1. Prueba [0]: debe responder 0. El costo es O(n + U), donde U = 101 es la cantidad de valores posibles, y la memoria es O(U).'),
    s('Qué cambia con otra pregunta', 'Si necesitas consultar el quinto voto recibido, guarda la lista en un vector: el acceso por índice cuesta O(1). Si quieres asociar nombre y puntuación, una pareja permite mantener ambos datos juntos. Si necesitas agregar al final, vector ofrece push_back.\n\npush_back cuesta O(1) amortizado: algunas ampliaciones mueven varios elementos, pero una secuencia de inserciones conserva ese promedio. Insertar al principio de un vector puede desplazar toda la lista. Elige la estructura por las operaciones y la información que no puedes perder.'),
  ]),
  'usaco-bronze-simulation': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Una alcancía comienza con saldo s. Recibimos n operaciones: D x deposita x; R x intenta retirar x. Un retiro se acepta solo si alcanza el saldo; si no alcanza, no cambia nada. Queremos el saldo final.\n\nn puede ser cero y llega hasta 100 000. El saldo inicial y cada x están entre 0 y 10⁹. Con saldo 10, las operaciones R 7, D 2 y R 6 dejan 5: el último retiro se rechaza.', { example: { input: '3 10\nR 7\nD 2\nR 6\n', output: '5\n' } }),
    s('El estado es lo que cambia', 'Para saber qué ocurre en la siguiente operación solo necesitamos el saldo actual. No hace falta conservar toda la historia de depósitos y retiros. Ese saldo es el **estado** de nuestra simulación.\n\nSimular significa aplicar las reglas en el orden indicado. No podemos sumar todos los depósitos primero: eso podría permitir un retiro que, cuando llegó, no tenía fondos.', { picture: { caption: 'Cada operación usa el saldo dejado por la anterior.', rows: [{ label: 'Operación', values: ['Inicio', 'R 7', 'D 2', 'R 6'] }, { label: 'Saldo', values: ['10', '3', '5', '5'] }] } }),
    f('Traducir una operación', 'tipo guarda la letra y x la cantidad. Leemos ambos antes de decidir:', 'char tipo;\nlong long x;\ncin >> tipo >> x;\nif (tipo == \'D\') {\n    saldo += x;\n} else if (saldo >= x) {\n    saldo -= x;\n}', 'El enunciado garantiza que solo existen D y R. Por eso, si no es D, podemos tratarlo como un retiro. La comparación usa >=: retirar exactamente todo el saldo sí está permitido.\n\nSi el retiro no alcanza, ninguna rama modifica saldo. No lo ponemos en cero ni permitimos un valor negativo.'),
    complete(lesson, 'Repetimos esas reglas n veces y escribimos el saldo al final. saldo es long long porque muchos depósitos pueden acumular más de lo que cabe en int.', 'Prueba saldo 8 con R 10, D 5, R 8 y R 5. Los saldos deben ser 8, 13, 5 y 0. Una traza por operación permite encontrar la primera diferencia con el programa.'),
    s('Por qué basta seguir las reglas', 'Antes de la primera operación, saldo coincide con el saldo inicial. Cada vuelta aplica exactamente el cambio permitido: sumar, restar si alcanza o no hacer nada. Por tanto, después de cada vuelta representa el saldo real tras esas operaciones.\n\nEl programa hace O(n) trabajo y usa O(1) memoria adicional. Antes de elegir una simulación en otro problema, comprueba cuántos pasos puede exigir. Aquí n está limitado explícitamente.'),
  ]),
  'usaco-bronze-intro-complete': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Tenemos n valores y una suma objetivo t. Queremos contar cuántas ternas de posiciones diferentes suman exactamente t. El orden de las tres posiciones no importa.\n\nSe permite 3 ≤ n ≤ 100 y valores entre −10⁹ y 10⁹. Para [1, 2, 3, 4, 5] y objetivo 6, solo sirve la terna de valores 1, 2 y 3.', { example: { input: '5 6\n1 2 3 4 5\n', output: '1\n' } }),
    s('Definir una opción por sus posiciones', 'Una opción se representa con tres índices i, j y k. Exigir i < j < k evita elegir dos veces la misma posición y evita contar distintos órdenes de una misma terna.\n\nSi los datos son [1, 1, 1, 1] y t = 3, hay cuatro ternas de posiciones. Sus valores son iguales, pero cada una excluye a una posición distinta. No debemos fusionarlas.'),
    f('Tres elecciones, tres ciclos', 'Fijamos i, luego una posición posterior j y finalmente otra posterior k:', 'long long total = 0;\nfor (int i = 0; i < n; ++i) {\n    for (int j = i + 1; j < n; ++j) {\n        for (int k = j + 1; k < n; ++k) {\n            if (a[i] + a[j] + a[k] == t) ++total;\n        }\n    }\n}', 'Cada terna válida tiene un menor índice, uno intermedio y uno mayor. Los ciclos visitan exactamente esa combinación una vez. Después de generarla, la condición decide si cuenta.\n\nLos valores y t son long long para que una suma de tres cantidades se calcule con espacio suficiente.'),
    s('Seguir un caso pequeño', 'Con cuatro posiciones, las ternas son (0,1,2), (0,1,3), (0,2,3) y (1,2,3). Para valores [1,2,3,4] y t = 6, sus sumas son 6, 7, 8 y 9. Solo la primera aumenta total.\n\nEscribir esta lista antes del código ayuda a detectar un límite incorrecto, como empezar k en j y repetir una posición.'),
    complete(lesson, 'El programa lee el objetivo junto con n, guarda la lista y evalúa las ternas. La salida es una cantidad, no las posiciones ni los valores que encontró.', 'Prueba [1, 1, 1, 1] con objetivo 3: debe dar 4. Después usa un objetivo que ninguna terna alcance: debe dar 0.'),
    s('Cuántas ternas revisamos', 'Hay n(n − 1)(n − 2)/6 ternas. Para n = 100 son 161 700, así que la búsqueda O(n³) cabe en el tamaño elegido. La memoria del vector es O(n).\n\nNo extiendas esta solución a n = 100 000 sin cambiar la idea. La búsqueda exhaustiva es útil cuando puedes cubrir todas las opciones dentro de los límites, no solo cuando el código tiene pocos ciclos.'),
  ]),
  'usaco-bronze-complete-rec': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Recibimos n números y un objetivo t. Queremos contar cuántos subconjuntos de posiciones suman t. Cada posición puede elegirse una vez o no elegirse. Incluimos la elección vacía, cuya suma es cero.\n\nn va de 0 a 20. Para [1, 2, 3] y objetivo 3 hay dos respuestas: elegir las posiciones de 1 y 2, o elegir solamente la de 3.', { example: { input: '3 3\n1 2 3\n', output: '2\n' } }),
    s('Dividir la elección en preguntas de sí o no', 'En vez de escribir un ciclo por cada posición, hacemos una pregunta a la vez: ¿incluimos el dato actual? Una respuesta abre dos posibilidades, y luego ambas siguen con la posición siguiente.\n\nPara [1, 2], las decisiones producen vacío, {2}, {1} y {1, 2}. Hay cuatro subconjuntos. Una llamada recursiva es una función que se llama a sí misma para continuar con una tarea más pequeña.'),
    f('Describir una llamada antes de escribirla', 'Usaremos contar(i, suma). Significa: ya decidimos las posiciones anteriores a i, esas elecciones suman suma y falta decidir desde i hasta el final.\n\nCuando i llega al tamaño del arreglo, no hay más decisiones:', 'if (i == (int)a.size()) {\n    return suma == objetivo;\n}', 'La comparación vale true o false. Al devolverla como long long se convierte en 1 o 0: esta elección completa cuenta si su suma coincide con el objetivo.\n\nEste es el caso base, la condición que detiene las llamadas. Con n = 0 se alcanza inmediatamente: el subconjunto vacío cuenta solo si t es cero.'),
    f('Continuar por las dos opciones', 'Si todavía queda un dato, sumamos las respuestas de no elegirlo y de elegirlo:', 'return contar(i + 1, suma)\n     + contar(i + 1, suma + a[i]);', 'La primera llamada deja la suma igual. La segunda agrega a[i]. Ambas avanzan i, de modo que tarde o temprano llegan al caso base.\n\nsuma se pasa por valor. Cada llamada recibe su propia copia; la rama que agrega el dato no cambia la suma de su hermana. Si usáramos una lista compartida de elementos elegidos, tendríamos que deshacer la inserción al volver: eso se conoce como retroceso o backtracking.'),
    s('Seguir las dos respuestas de la muestra', 'Para llegar a {1, 2}, elegimos la primera posición, elegimos la segunda y rechazamos la tercera: sumas 0 → 1 → 3 → 3. Para llegar a {3}, rechazamos las primeras dos y elegimos la última: 0 → 0 → 0 → 3.\n\nCada subconjunto determina una secuencia única de sí y no. Por eso no falta ninguno ni contamos una misma elección de posiciones dos veces. Dos posiciones con valor 3 siguen ofreciendo dos elecciones distintas.', { picture: { caption: 'Las posiciones se deciden en el mismo orden en todas las ramas.', rows: [{ label: 'Posición', values: ['0: valor 1', '1: valor 2', '2: valor 3'] }, { label: 'Primera respuesta', values: ['Sí', 'Sí', 'No'] }, { label: 'Segunda respuesta', values: ['No', 'No', 'Sí'] }] } }),
    complete(lesson, 'La llamada inicial es contar(0, 0): no decidimos ninguna posición y la suma comienza en cero. a y objetivo se declaran fuera de main para que contar pueda consultarlos.', 'Prueba [3, 3] con objetivo 3: debe dar 2. Prueba n = 0 y objetivo 0: debe dar 1. Hay 2ⁿ elecciones; esta implementación tarda O(2ⁿ) y mantiene como máximo n llamadas pendientes, O(n) memoria además del arreglo.'),
    f('Si importa el orden, son permutaciones', 'Elegir un subconjunto no decide un orden para sus elementos. Para enumerar todos los órdenes de una lista, puedes ordenar primero y usar next_permutation:', 'sort(a.begin(), a.end());\ndo {\n    // Aquí se procesa el orden actual de a.\n} while (next_permutation(a.begin(), a.end()));', 'Para tres valores distintos hay 3 × 2 × 1 = 6 órdenes, llamados permutaciones. Para n distintos hay n!, mucho más que 2ⁿ cuando n crece. Con valores repetidos, esta función recorre órdenes de valores distintos si empiezas desde el ordenado. Si las identidades importan, debes distinguir las posiciones.\n\nEsta es otra tarea: no reemplaza la búsqueda de subconjuntos del programa anterior.'),
  ]),
  'usaco-bronze-intro-sorting': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Recibimos una lista y queremos contar cuántos valores distintos contiene. Las apariciones repetidas cuentan una sola vez. n puede ser cero y llega hasta 100 000.\n\nPara [4, 2, 4, 1, 2, 2], los valores distintos son 1, 2 y 4. La respuesta es 3.', { example: { input: '6\n4 2 4 1 2 2\n', output: '3\n' } }),
    s('Comparar solo vecinos todavía no sirve', 'En la lista original los dos cuatros están separados. Revisar solo si un valor es diferente del anterior contaría grupos de posiciones, no valores distintos.\n\nAl ordenar obtenemos [1, 2, 2, 2, 4, 4]. Ahora todas las copias de un mismo valor quedan juntas. Basta contar dónde empieza cada grupo.'),
    f('Ordenar y contar los comienzos de grupo', 'El primer elemento inicia un grupo. Cada elemento posterior inicia otro solo si cambia respecto al anterior:', 'sort(a.begin(), a.end());\nint distintos = 0;\nfor (int i = 0; i < n; ++i) {\n    if (i == 0 || a[i] != a[i - 1]) ++distintos;\n}', 'C++ evalúa `||` de izquierda a derecha y no evalúa la derecha si la izquierda ya es verdadera. Por eso, cuando i es cero, no consulta a[−1].\n\nSi n = 0 el ciclo no se ejecuta y la respuesta queda en cero. No inicializamos distintos en uno sin revisar si existe un primer dato.'),
    s('Seguir el contador', 'En [1, 2, 2, 2, 4, 4], las posiciones que empiezan grupos son 0, 1 y 4. El contador pasa por 1, 2, 2, 2, 3 y 3.\n\nCada valor distinto tiene exactamente un primer elemento dentro de su bloque ordenado. Contar esos inicios equivale a contar los valores.', { picture: { caption: 'Solo se marca el inicio de cada grupo de iguales.', rows: [{ label: 'Valores ordenados', values: ['1', '2', '2', '2', '4', '4'], highlight: [0, 1, 4] }, { label: 'distintos después', values: ['1', '2', '2', '2', '3', '3'] }] } }),
    complete(lesson, 'El programa conserva todas las apariciones; no necesita borrarlas para contar sus grupos. Los valores pueden ser negativos: sort también los ordena.', 'Prueba una lista vacía, una de todos iguales y otra de todos distintos. Ordenar cuesta O(n log n), y el recorrido posterior O(n). El total sigue siendo O(n log n).'),
    s('Otra pregunta que aprovecha los vecinos', 'Ordenar también ayuda a buscar la menor distancia entre dos valores. Si eliges dos valores separados por otros, su diferencia se divide en diferencias vecinas no negativas. Alguna pareja vecina será al menos tan cercana.\n\nLa propiedad útil cambia según la pregunta: aquí agrupamos iguales; en el problema de tiempos cercanos compararemos diferencias. En ambos casos debes explicar qué garantiza el orden antes de descartar otras parejas.'),
  ]),
  'usaco-bronze-intro-sets': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Llegan n identificadores de estudiantes. Queremos contar cuántas llegadas repiten un identificador visto anteriormente. La primera llegada de cada identificador no cuenta.\n\nn está entre 0 y 100 000 y los identificadores entre 0 y 10⁹. Para [5, 2, 5, 8, 2, 5], las últimas apariciones de 5, 2 y 5 producen tres repeticiones.', { example: { input: '6\n5 2 5 8 2 5\n', output: '3\n' } }),
    s('Guardar presencia sin reservar mil millones de casillas', 'Una tabla de frecuencias por identificador sería enorme para ese rango. Podemos guardar solo los identificadores que realmente aparecen.\n\nUn set es un conjunto: conserva un ejemplar de cada valor. Insertar 5 varias veces no crea varias copias. Para esta tarea basta preguntar si el identificador ya pertenece al conjunto.'),
    f('Consultar antes de insertar', 'Necesitamos <set>. vistos comienza vacío y repetidos en cero:', 'set<long long> vistos;\nint repetidos = 0;\n// Dentro del ciclo, después de leer x:\nif (vistos.find(x) != vistos.end()) ++repetidos;\nvistos.insert(x);', '`find(x)` busca el valor y devuelve una posición, llamada iterador. Si no existe, devuelve end, una marca que no corresponde a un elemento.\n\nLa consulta va antes de insertar. Si insertaras primero, incluso la primera llegada parecería una repetición.'),
    s('Seguir las llegadas', 'Tras 5 y 2, el conjunto es {2, 5} y repetidos vale 0. El siguiente 5 ya existe: aumenta a 1. El 8 se agrega sin aumentar la cuenta. Luego 2 y 5 la llevan a 2 y 3.\n\nEl conjunto final tiene tres valores, pero ese tamaño responde otra pregunta: cuántos identificadores distintos hubo. Nuestra salida cuenta llegadas repetidas.'),
    complete(lesson, 'set mantiene los valores ordenados y permite buscar e insertar en O(log d), donde d es la cantidad de valores distintos guardados. Procesar n llegadas cuesta O(n log n) en el peor caso y usa O(n) memoria.', 'Prueba tres llegadas del mismo identificador: la respuesta debe ser 2. Con n = 0 debe ser 0.'),
    f('Cuando también necesitas cantidades', 'Un map asocia una clave con un dato. Si datos es un vector de identificadores, podemos guardar sus frecuencias así:', 'map<long long, int> frecuencia;\nfor (long long x : datos) {\n    ++frecuencia[x];\n}', 'Necesitas <map>. `frecuencia[x]` crea la clave con valor cero si aún no existe y luego la incrementa. Si solo quieres consultar sin insertar, usa find.\n\nset guarda presencia; map puede guardar cantidades u otra información. multiset conserva varias copias: borrar por valor elimina todas las copias de ese valor, mientras borrar por iterador elimina una. Las variantes unordered no conservan orden y usan otra organización; no necesitas cambiarlas para resolver este problema.'),
  ]),
  'usaco-bronze-casework': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Dos cintas cubren segmentos de una recta: la primera va de a a b y la segunda de c a d. Queremos la longitud del tramo que cubren ambas. Si están separadas o solo se tocan, la respuesta es cero.\n\nLos extremos están ordenados dentro de cada segmento y van de −10⁹ a 10⁹. Para [1, 7] y [4, 10], el tramo compartido es [4, 7] y mide 3.', { example: { input: '1 7 4 10\n', output: '3\n' } }),
    s('Dibujar los casos antes de escribir condiciones', 'Podrían estar separados, cruzarse parcialmente, coincidir o quedar uno dentro del otro. Una condición que solo revise si c está dentro del primer segmento falla cuando el segundo contiene al primero.\n\nEl análisis por casos sirve para cubrir todas las formas de una entrada. Las fronteras también cuentan: tocarse en un punto no es compartir una longitud positiva.'),
    s('Encontrar el principio y el final comunes', 'Para pertenecer a ambos segmentos, una posición tiene que estar después de sus dos inicios. El inicio común es max(a, c). También debe quedar antes de ambos finales: el final común es min(b, d).\n\nSi el final común está antes del inicio común, no existe tramo compartido. Si coinciden, la longitud es cero. Si está después, restamos inicio al final.'),
    f('Reunir los casos en una fórmula', 'Guardamos los dos extremos calculados y evitamos una longitud negativa:', 'long long inicio = max(a, c);\nlong long fin = min(b, d);\ncout << max(0LL, fin - inicio) << "\\n";', '`0LL` escribe el cero como long long, el mismo tipo que la resta. Así max compara dos valores del mismo tipo.\n\nPara [1,7] y [4,10], inicio vale 4 y fin vale 7. Para [1,2] y [4,6], inicio vale 4 y fin vale 2; max convierte esa resta negativa en cero.'),
    complete(lesson, 'La fórmula cubre separación, contacto, cruce, contención e igualdad sin escribir una rama para cada dibujo. Hace O(1) operaciones y usa O(1) memoria.', 'Prueba [2,4] con [6,8], [3,7], [0,9], [2,4] y [4,6]. Las longitudes deben ser 0, 1, 2, 2 y 0.'),
    s('Longitud no es cantidad de puntos enteros', 'El intervalo [3,5] mide dos unidades, pero contiene tres enteros: 3, 4 y 5. Dos segmentos que se tocan en 4 comparten un punto entero y longitud cero.\n\nSi la tarea cambiara a contar posiciones enteras, tendrías que cambiar la fórmula de respuesta. La palabra «cerrado» incluye los extremos, pero no les da una longitud adicional.'),
  ]),
  'usaco-bronze-intro-greedy': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Una sala recibe propuestas de talleres con hora de inicio y fin. Queremos aceptar la mayor cantidad sin que se superpongan. Todos cuentan lo mismo y uno puede comenzar justo cuando otro termina.\n\nHay hasta 100 000 propuestas, con 0 ≤ inicio < fin ≤ 10⁹. Para [0,3], [3,6] y [2,4], podemos elegir las primeras dos. La respuesta es 2.', { example: { input: '3\n0 3\n3 6\n2 4\n', output: '2\n' } }),
    s('Una elección que parece buena, pero falla', 'El taller [2,4] es el más corto de los tres. Si lo eliges primero, choca con los otros dos y solo aceptas uno. La duración más corta no garantiza la mayor cantidad.\n\nProbemos otra regla: elegir el taller que termine antes y después repetir entre los que puedan empezar cuando la sala quede libre. En la muestra elegimos [0,3] y luego [3,6].'),
    s('Por qué terminar antes es una elección segura', 'Toma una agenda con la mayor cantidad posible de talleres. Si su primer taller no es el que termina antes, sustitúyelo por el de final más temprano. Los talleres que seguían todavía caben: la sala no queda ocupada por más tiempo.\n\nLa sustitución conserva la cantidad. Por tanto, existe una agenda óptima que empieza con nuestra elección. Después de fijarla, aplicamos el mismo argumento a los talleres compatibles restantes.'),
    f('Ordenar por hora de fin', 'Guardamos cada taller como (fin, inicio). Las parejas de C++ se ordenan primero por su primer dato y luego por el segundo:', 'vector<pair<long long, long long>> a;\nfor (int i = 0; i < n; ++i) {\n    long long s, e;\n    cin >> s >> e;\n    a.push_back({e, s});\n}\nsort(a.begin(), a.end());', 'La entrada usa inicio y fin; el vector invierte ese orden a propósito. En cada pareja, first será el final y second el inicio. Empates de final pueden resolverse por inicio sin cambiar el argumento.'),
    f('Aceptar solo los que todavía caben', 'libre guarda la hora desde la que podemos usar la sala. Como los inicios no son negativos, empieza en cero:', 'long long libre = 0;\nint total = 0;\nfor (auto p : a) {\n    if (p.second >= libre) {\n        ++total;\n        libre = p.first;\n    }\n}', 'Un taller incompatible se rechaza sin cambiar libre. Para [0,3], [2,4] y [3,6] en orden de final, aceptamos el primero, rechazamos el segundo y aceptamos el tercero. `>=` permite unirlos justo en la hora 3.'),
    complete(lesson, 'El programa ordena en O(n log n) y recorre una vez en O(n). Guarda O(n) parejas. Con n = 0 no acepta ninguna y escribe cero.', 'Prueba talleres consecutivos, otros que se cruzan todos y varios con el mismo final. Si se exigiera tiempo de limpieza, habría que incorporarlo a libre; la condición actual no lo contempla.'),
    s('El objetivo forma parte de la demostración', 'Si cada taller ofreciera un premio distinto y quisieras maximizar dinero, escoger el final más temprano podría fallar. Un taller largo de premio cien puede valer más que dos cortos de premio uno.\n\nOtra regla voraz, comprar primero los objetos más baratos, sirve para maximizar cantidad con costos no negativos y objetos que cuentan igual. Se justifica intercambiando un objeto caro por uno barato. Cambiar el objetivo exige revisar otra vez el argumento.'),
  ]),
  'usaco-bronze-intro-graphs': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Un campus tiene n edificios y m caminos de doble sentido. Queremos imprimir cuántos caminos llegan directamente a cada edificio. La entrada da n, m y luego m parejas de edificios conectados.\n\nLos edificios se numeran del 1 al n. No hay caminos de un edificio consigo mismo ni caminos repetidos. Para las conexiones 1–2, 2–3 y 2–4, las cantidades son 1, 3, 1 y 1.', { example: { input: '4 3\n1 2\n2 3\n2 4\n', output: '1 3 1 1\n' } }),
    s('Poner nombre a las partes del dibujo', 'Un **grafo** representa objetos y conexiones. Cada edificio es un vértice, también llamado nodo. Cada camino es una arista. Como se puede recorrer en ambos sentidos, el grafo es no dirigido.\n\nEl grado de un vértice es cuántas aristas llegan a él. Aquí, sin lazos ni aristas repetidas, también coincide con su cantidad de vecinos directos. No cuenta todos los edificios a los que puedas llegar pasando por otros.'),
    f('Contar ambos extremos de cada camino', 'Para responder grados basta un contador por edificio. El vector usa índices desde cero, así que restamos uno a los números de entrada:', 'vector<int> grado(n, 0);\nfor (int i = 0; i < m; ++i) {\n    int u, v;\n    cin >> u >> v;\n    ++grado[u - 1];\n    ++grado[v - 1];\n}', 'La arista 1–2 aumenta el grado de 1 y de 2. Después 2–3 aumenta el de 2 y el de 3. Después 2–4 vuelve a aumentar el de 2 y el de 4.\n\nCada arista suma dos al total de grados, así que al final deben sumar 2m. En la muestra, 1 + 3 + 1 + 1 = 6.'),
    complete(lesson, 'Guardamos n contadores incluso si un edificio no aparece en ninguna arista. Ese edificio está aislado y su grado es cero. El programa tarda O(n + m) y usa O(n) memoria.', 'Prueba n = 3 y m = 0: debe escribir 0 0 0. La ausencia de caminos no elimina los edificios.'),
    f('Si después necesitas saber quiénes son los vecinos', 'Los grados no guardan identidades. Para conservarlas usamos una lista por vértice, llamada lista de adyacencia:', 'vector<vector<int>> vecinos(n);\n// Después de convertir u y v a índices desde cero:\nvecinos[u].push_back(v);\nvecinos[v].push_back(u);', 'Para la muestra, las listas por edificio son {2}, {1,3,4}, {2} y {2}, expresadas con números desde uno. La representación interna guarda los índices desde cero.\n\nLas listas ocupan O(n + m). Una matriz n × n puede consultar una arista en O(1), pero ocupa O(n²); no conviene para n = 100 000.'),
    s('No todas las conexiones significan lo mismo', 'En una calle de un solo sentido guardarías solo la dirección permitida. Si cada camino tiene distancia, esa cantidad es un peso y también debe almacenarse. El enunciado define cuál de esos modelos necesitas.\n\nEn 1–2–3 puedes llegar de 1 a 3 sin una arista directa. Un camino es una secuencia de aristas; una componente reúne los vértices conectados mediante caminos. Más adelante BFS y DFS explorarán esa relación. El grado responde solamente la pregunta de vecinos inmediatos.'),
  ]),
  'usaco-bronze-rect-geo': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Dos patios rectangulares están dibujados sobre un plano y queremos el área que comparten. Cada rectángulo tiene lados paralelos a los ejes y se describe por su esquina inferior izquierda y su esquina superior derecha.\n\nLa entrada contiene x1, y1, x2, y2 para el primer patio y x3, y3, x4, y4 para el segundo. Las coordenadas van de −10⁹ a 10⁹. Para (0,0)–(5,4) y (2,1)–(7,3), el área común es 6.', { example: { input: '0 0 5 4 2 1 7 3\n', output: '6\n' } }),
    s('Separar ancho y alto', 'El primer patio ocupa horizontalmente [0,5] y verticalmente [0,4]. El segundo ocupa [2,7] y [1,3].\n\nHorizontalmente coinciden de 2 a 5: ancho 3. Verticalmente coinciden de 1 a 3: alto 2. Como la región común vuelve a ser un rectángulo, su área es 3 × 2 = 6.', { picture: { caption: 'La región debe coincidir en los dos ejes al mismo tiempo.', rows: [{ label: 'Eje', values: ['Horizontal, x', 'Vertical, y'] }, { label: 'Primer patio', values: ['0 a 5', '0 a 4'] }, { label: 'Segundo patio', values: ['2 a 7', '1 a 3'] }, { label: 'Parte común', values: ['2 a 5: ancho 3', '1 a 3: alto 2'] }] } }),
    f('Calcular una longitud común por eje', 'Usamos la fórmula de intersección de segmentos en cada dimensión:', 'long long ancho = max(0LL, min(x2, x4) - max(x1, x3));\nlong long alto = max(0LL, min(y2, y4) - max(y1, y3));\ncout << ancho * alto << "\\n";', 'Si no hay cruce horizontal, ancho queda en cero. Aunque los intervalos verticales coincidan, el área será cero. Lo mismo ocurre si solo comparten un borde.\n\nNo sumamos uno a las longitudes: estamos midiendo superficie continua, no contando puntos enteros de una cuadrícula.'),
    complete(lesson, 'En el programa, las ocho variables a, b, c, d, e, f, g y h corresponden, en ese orden, a x1, y1, x2, y2, x3, y3, x4 y y4. Las cuentas son las mismas que acabamos de escribir.', 'Prueba dos rectángulos separados y dos que solo comparten un borde. Ambos tienen área común cero. Prueba también dos rectángulos iguales: el área común debe ser toda su área.'),
    s('Coordenadas grandes y negativas', 'Un tramo de −4 a 2 tiene longitud 2 − (−4) = 6. Las coordenadas negativas no exigen otra fórmula. Lo que mide el ancho es la diferencia entre extremos.\n\nCada dimensión puede llegar a 2 × 10⁹ y el producto a 4 × 10¹⁸. Por eso usamos long long desde las coordenadas y antes de multiplicar. Hacemos O(1) operaciones y usamos O(1) memoria.'),
    s('Otras áreas que no debes confundir', 'Para saber cuánto cubren entre ambos, suma sus áreas y resta la intersección, que estaba contada dos veces. Para saber cuánto queda visible del primero, resta al área del primero la parte común.\n\nEl rectángulo mínimo que contiene ambos puede incluir espacio vacío entre ellos. Su área no es necesariamente la cubierta. Antes de usar una fórmula, señala qué región pide el problema.'),
  ]),
  'usaco-bronze-ad-hoc': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Un robot empieza en la posición cero de una recta. Cada paso lo mueve exactamente una unidad a la derecha o a la izquierda. Queremos saber si puede terminar en x después de exactamente k pasos. No hay paredes ni límites en la recta.\n\nLa entrada contiene x, entre −10⁹ y 10⁹, y k, entre 0 y 10⁹. Respondemos SI o NO. Para x = 2 y k = 4, sí puede: derecha, derecha, derecha, izquierda.', { example: { input: '2 4\n', output: 'SI\n' } }),
    s('Una condición que todavía no alcanza', 'La distancia al destino es |x|. Si k es menor, no alcanza el número de pasos. Pero tener pasos suficientes no garantiza llegar exactamente al final.\n\nPara x = 2 y k = 3, después de tres pasos solo puedes terminar en −3, −1, 1 o 3. Todos son impares. Ninguno es 2.'),
    s('Lo que cambia de manera predecible', 'Cada paso cambia la paridad de la posición: de par a impar o de impar a par. Después de k pasos, la posición final tiene la misma paridad que k.\n\nPor eso, además de k ≥ |x|, necesitamos que k − |x| sea par. Podemos comprobarlo con residuo módulo dos. Una observación de este tipo permite resolver un problema ad hoc: la idea proviene de sus reglas concretas.'),
    s('Construir una ruta cuando se cumplen ambas', 'Da |x| pasos hacia el destino. Si x es negativo, serán a la izquierda. Llegaste a x y sobran k − |x| pasos.\n\nSi ese sobrante es par, gástalo en parejas de ida y vuelta: derecha e izquierda. Cada pareja usa dos pasos y termina donde empezó. Así las condiciones no solo descartan imposibles; también construyen una ruta para todos los casos aceptados.'),
    f('Escribir las dos comprobaciones', 'Calculamos la distancia sin signo y después comprobamos distancia y paridad:', 'long long distancia = x < 0 ? -x : x;\nbool posible = k >= distancia && (k - distancia) % 2 == 0;\ncout << (posible ? "SI" : "NO") << "\\n";', 'La expresión `condicion ? a : b` selecciona a cuando es verdadera y b cuando es falsa. La primera la usamos para el valor absoluto; la última para elegir el texto de salida.\n\n`&&` exige ambas condiciones. Si no alcanza la distancia, el caso ya es imposible.'),
    complete(lesson, 'El programa usa una cantidad fija de cuentas: O(1) tiempo y memoria. No necesitamos generar las 2ᵏ secuencias de pasos.', 'Prueba 0 0, 0 1, 3 6 y −3 5. Deben salir SI, NO, NO y SI. La recta sin límites permite las parejas de ida y vuelta usadas en la demostración.'),
    s('Otra forma de comprobar la observación', 'Si r es la cantidad de pasos a la derecha y l a la izquierda, entonces r + l = k y r − l = x. De ahí r = (k + x)/2 y l = (k − x)/2. Deben ser enteros no negativos, que son exactamente las condiciones anteriores.\n\nSi el robot pudiera quedarse quieto, la condición de paridad dejaría de ser necesaria: podría gastar un paso sin moverse. Cuando cambian las operaciones, revisa qué parte de la demostración sigue siendo cierta.'),
  ]),
  'usaco-bronze-bronze-conclusion': lesson => walkthrough([
    s('El problema que vamos a resolver', 'Recibimos n tiempos de entrenamiento y queremos la menor diferencia absoluta entre dos posiciones distintas. Los tiempos repetidos son válidos y producen diferencia cero.\n\nSe cumple 2 ≤ n ≤ 100 000 y cada tiempo va de 0 a 10⁹. Para [12, 5, 20, 9, 30], la respuesta es 3: los tiempos 9 y 12 son los más cercanos.', { example: { input: '5\n12 5 20 9 30\n', output: '3\n' } }),
    s('Una solución directa para comprobar la pregunta', 'Podemos enumerar todas las parejas i < j, calcular su diferencia absoluta y guardar la menor. Esa búsqueda exhaustiva es correcta porque visita cada opción.\n\nPara cien mil datos requiere casi cinco mil millones de parejas. Los límites nos obligan a buscar otra forma de evitar comparaciones. La solución lenta todavía puede ayudarnos a comprobar entradas pequeñas.'),
    s('Ordenar para ver a los vecinos', 'Después de ordenar, los tiempos son [5, 9, 12, 20, 30]. Las diferencias vecinas son 4, 3, 8 y 10. La menor es 3.\n\n¿Por qué no comparar también 5 y 20? Entre ellos están 9 y 12. La diferencia 20 − 5 se divide en tres diferencias vecinas no negativas: 4 + 3 + 8. Al menos una vecina no será mayor que la diferencia completa. Por tanto, existe una pareja óptima entre vecinos.', { picture: { caption: 'Basta revisar cada separación entre dos vecinos ordenados.', rows: [{ label: 'Tiempos', values: ['5', '9', '12', '20', '30'] }, { label: 'Diferencia con anterior', values: ['No tiene', '4', '3', '8', '10'], highlight: [2] }] } }),
    f('Inicializar con una pareja que existe', 'El enunciado garantiza al menos dos tiempos. Podemos empezar con la primera pareja ordenada:', 'sort(a.begin(), a.end());\nlong long mejor = a[1] - a[0];\nfor (int i = 2; i < n; ++i) {\n    mejor = min(mejor, a[i] - a[i - 1]);\n}', 'Inicializar mejor en cero sería incorrecto si todos los tiempos fueran distintos: ninguna diferencia positiva lo reduciría. La primera pareja da un valor real.\n\nComo la lista está ordenada, a[i] ≥ a[i − 1] y la resta ya es no negativa. No hace falta calcular su valor absoluto.'),
    complete(lesson, 'La lectura conserva los valores repetidos. Ordenamos y comparamos las n − 1 parejas vecinas. El programa imprime la diferencia, no los dos tiempos.', 'Prueba [8, 8]: debe dar 0. Prueba [1, 10]: debe dar 9. Ordenar cuesta O(n log n), recorrer O(n) y almacenar el vector O(n).'),
    s('Qué herramientas combinamos', 'Primero definimos candidatos y una solución exhaustiva. Después contamos su costo, aprovechamos el orden y justificamos qué parejas podían descartarse. Al programar, elegimos un valor inicial válido y cuidamos los índices.\n\nAnte otro problema, no decidas la técnica solo por el nombre del tema. Una lista corta puede permitir enumerar; un rango de valores pequeño puede permitir frecuencias; reglas de eventos pueden pedir simulación. Los datos, la salida y los límites orientan esa decisión.'),
    s('Una comprobación antes de avanzar', 'Intenta resolver una simulación, una enumeración de parejas y un problema que aproveche ordenar sin abrir sus soluciones. Para cada uno, explica qué guarda cada variable y por qué no pierde la respuesta.\n\nSi una parte falla, conserva un caso que muestre el problema y repasa esa decisión concreta. Poder justificar estos recorridos y sus costos será útil al estudiar las herramientas de Plata.'),
  ]),
};
